import React, { FormEvent, useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import './style.css';

type Professional={id:number;name:string;category:string;description?:string;city?:string;address?:string;rating:number;review_count:number;latitude:number;longitude:number;available?:number;verified?:number;distanceKm?:number;image?:string|null;completed_count?:number;joined_at?:string};
type User={id:number;name:string;username:string;role:'provider'|'client'|'admin';phone?:string;cep?:string;address?:string;city?:string;state?:string;image?:string|null};
type AdminUser={id:number;name:string;username:string;role:'provider'|'client'|'admin';phone?:string;city?:string;active:number;created_at:string;provider_id?:number|null;available?:number|null;verified?:number|null;rating?:number|null;review_count?:number|null};
type AdminReview={id:number;rating:number;comment?:string;created_at:string;client_name:string;provider_name:string;provider_id:number};
type SessionData={user:User;provider?:any;services?:any[]};
type ProfileDetail={professional:Professional;services:any[];reviews:any[];portfolio?:PortfolioItem[]};
type ServiceRequest={id:number;title:string;description:string;address?:string;status:string;created_at:string;updated_at?:string;scheduled_at?:string;provider_id?:number;provider_name?:string;category?:string;client_name?:string;client_phone?:string;client_city?:string;quote_id?:number;quote_price?:number;quote_message?:string;quote_status?:string;review_id?:number};
type Notice={id:number;title:string;message:string;kind:string;read_at?:string|null;created_at:string;link_request_id?:number|null};
type PortfolioItem={id:number;file_url:string;caption?:string;created_at:string};
type ChatMessage={id:number;sender_user_id:number;sender_name:string;message_type:'text'|'location';message?:string;latitude?:number;longitude?:number;created_at:string};

const examples=['Eletricista','Encanador','Técnico em informática','Pintor','Pedreiro','Diarista','Mecânico','Refrigeração'];
const statusLabel:Record<string,string>={open:'Solicitado',quoted:'Orçamento recebido',accepted:'Orçamento aceito',in_progress:'Serviço em andamento',completed:'Concluído',cancelled:'Cancelado'};
const BRL=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});
function token(){return localStorage.getItem('servperto_token')||''}
async function api(path:string,options:RequestInit={}){const headers=new Headers(options.headers);if(options.body&&!headers.has('content-type'))headers.set('content-type','application/json');const r=await fetch(path,{...options,headers});let body:any=null;try{body=await r.json()}catch{body={}}if(!r.ok)throw new Error(body.detail||body.error||`Erro ${r.status}`);return body}
function authHeaders(){return {authorization:`Bearer ${token()}`}}
function distanceKm(a:number,b:number,c:number,d:number){const R=6371,toRad=(x:number)=>x*Math.PI/180;const dLat=toRad(c-a),dLon=toRad(d-b);const q=Math.sin(dLat/2)**2+Math.cos(toRad(a))*Math.cos(toRad(c))*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(q))}
function stars(n:number){return '★★★★★'.slice(0,Math.round(n))+'☆☆☆☆☆'.slice(Math.round(n))}
function Avatar({name,image,big=false}:{name:string;image?:string|null;big?:boolean}){return image?<img className={`avatar photo ${big?'big':''}`} src={image} alt={`Foto de ${name}`}/>:<div className={`avatar ${big?'big':''}`}>{name.charAt(0).toUpperCase()}</div>}
async function compressProfileImage(file:File):Promise<string>{if(!file.type.startsWith('image/'))throw new Error('Selecione um arquivo de imagem.');if(file.size>8*1024*1024)throw new Error('A imagem original deve ter no máximo 8 MB.');const url=URL.createObjectURL(file);try{const img=await new Promise<HTMLImageElement>((ok,fail)=>{const i=new Image();i.onload=()=>ok(i);i.onerror=()=>fail(new Error('Não foi possível abrir a imagem.'));i.src=url});const max=512,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale));const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');if(!ctx)throw new Error('Navegador sem suporte para processar imagem.');ctx.drawImage(img,0,0,w,h);return c.toDataURL('image/jpeg',0.8)}finally{URL.revokeObjectURL(url)}}


type BeforeInstallPromptEvent = Event & { prompt:()=>Promise<void>; userChoice:Promise<{outcome:'accepted'|'dismissed'}> };
function InstallAppButton({compact=false}:{compact?:boolean}){
  const[prompt,setPrompt]=useState<BeforeInstallPromptEvent|null>(null);
  const[installed,setInstalled]=useState(false);
  useEffect(()=>{
    const standalone=window.matchMedia?.('(display-mode: standalone)').matches||(navigator as any).standalone===true;
    if(standalone)setInstalled(true);
    const h=(e:Event)=>{e.preventDefault();setPrompt(e as BeforeInstallPromptEvent)};
    const done=()=>{setInstalled(true);setPrompt(null)};
    window.addEventListener('beforeinstallprompt',h);
    window.addEventListener('appinstalled',done);
    return()=>{
      window.removeEventListener('beforeinstallprompt',h);
      window.removeEventListener('appinstalled',done);
    };
  },[]);
  if(installed)return compact?null:<span className="appInstalled">✓ App instalado</span>;
  return <button className={compact?'installMini':'installApp'} onClick={async()=>{
    if(prompt){
      await prompt.prompt();
      await prompt.userChoice;
      setPrompt(null);
    }else{
      alert('No Android: abra o menu do navegador e toque em “Adicionar à tela inicial” ou “Instalar app”.');
    }
  }}>{compact?'📲':'📲 Instalar ServPerto'}</button>;
}
function PwaRegister(){useEffect(()=>{if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})},[]);return null}

function Modal({children,onClose,wide=false}:{children:React.ReactNode,onClose:()=>void,wide?:boolean}){return <div className="modalBackdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className={`modal ${wide?'wide':''}`}><button className="close" onClick={onClose}>×</button>{children}</div></div>}

function MapPanel({items,userPos,onOpen}:{items:Professional[],userPos:{lat:number,lng:number}|null,onOpen:(id:number)=>void}){const ref=useRef<HTMLDivElement>(null),mapRef=useRef<L.Map|null>(null),layerRef=useRef<L.LayerGroup|null>(null);useEffect(()=>{if(!ref.current||mapRef.current)return;const m=L.map(ref.current,{zoomControl:true}).setView([-3.119,-60.0217],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(m);mapRef.current=m;layerRef.current=L.layerGroup().addTo(m);setTimeout(()=>m.invalidateSize(),50)},[]);useEffect(()=>{const m=mapRef.current,l=layerRef.current;if(!m||!l)return;l.clearLayers();const bounds:L.LatLngExpression[]=[];items.forEach(p=>{const pos:[number,number]=[p.latitude,p.longitude];bounds.push(pos);const safeName=String(p.name||'Profissional').replace(/[<>&\"']/g,'');const safeImage=p.image?String(p.image).replace(/"/g,'&quot;'):'';const photo=safeImage?`<div class="servpertoMapPhoto"><img src="${safeImage}" alt="Foto de ${safeName}"></div>`:`<div class="servpertoMapPhoto fallback"><span>${safeName.charAt(0).toUpperCase()}</span></div>`;const statusClass=p.available===0?'unavailable':'available';const statusText=p.available===0?'Indisponível':'Disponível';const icon=L.divIcon({className:'servpertoMapIconWrap',html:`<div class="servpertoMapPin ${statusClass} ${p.verified?'verified':''}">${photo}<i class="mapStatus ${statusClass}" title="${statusText}"></i></div>`,iconSize:[54,64],iconAnchor:[27,61],popupAnchor:[0,-54]});const marker=L.marker(pos,{icon}).addTo(l).bindPopup(`<div class="mapPopup"><b>${safeName}</b><span>${p.category||'Serviços'}</span><span class="${statusClass}">${p.available===0?'🟠':'🟢'} ${statusText}</span><span>⭐ ${p.review_count?Number(p.rating||0).toFixed(1):'Novo no ServPerto'}</span></div>`);marker.on('popupopen',()=>{const el=marker.getPopup()?.getElement();if(el){const content=el.querySelector('.leaflet-popup-content');if(content&&!content.querySelector('.mapProfileBtn')){const btn=document.createElement('button');btn.className='mapProfileBtn';btn.textContent='Ver perfil';btn.onclick=()=>onOpen(p.id);content.appendChild(btn)}}})});if(userPos){bounds.push([userPos.lat,userPos.lng]);L.circleMarker([userPos.lat,userPos.lng],{radius:9}).addTo(l).bindPopup('Sua localização')}if(bounds.length>1)m.fitBounds(L.latLngBounds(bounds),{padding:[35,35],maxZoom:14});else if(userPos)m.setView([userPos.lat,userPos.lng],13)},[items,userPos,onOpen]);return <div ref={ref} className="mapShell"/>}
function LoginModal({onClose,onLogin}:{onClose:()=>void,onLogin:()=>Promise<void>}){const[mode,setMode]=useState<'login'|'recover'>('login'),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setMsg('');const f=Object.fromEntries(new FormData(e.currentTarget).entries());try{if(mode==='login'){const out=await api('/api/auth/login',{method:'POST',body:JSON.stringify(f)});localStorage.setItem('servperto_token',out.token);await onLogin();onClose()}else{await api('/api/auth/recover',{method:'POST',body:JSON.stringify(f)});setMsg('Senha alterada. Agora você pode entrar.');setMode('login')}}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}return <Modal onClose={onClose}><div className="eyebrow">ACESSO SERVPERTO</div><h2>{mode==='login'?'Entrar na plataforma':'Recuperar senha'}</h2><form onSubmit={submit} className="formGrid one"><label>Nome de login<input name="username" required autoComplete="username"/></label>{mode==='login'?<label>Senha<input name="password" type="password" required autoComplete="current-password"/></label>:<><label>Código de recuperação<input name="recoveryCode" inputMode="numeric" maxLength={6} required/></label><label>Nova senha<input name="newPassword" type="password" minLength={8} required/></label></>}{msg&&<div className={msg.startsWith('Senha')?'okText':'errorText'}>{msg}</div>}<button className="primary" disabled={busy}>{busy?'Aguarde...':mode==='login'?'Entrar':'Alterar senha'}</button></form><button className="linkBtn" onClick={()=>{setMode(mode==='login'?'recover':'login');setMsg('')}}>{mode==='login'?'Esqueci minha senha':'Voltar ao login'}</button></Modal>}

function RegisterModal({onClose}:{onClose:()=>void}){const[role,setRole]=useState<'client'|'professional'>('client'),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false),[coords,setCoords]=useState<{lat:number,lng:number}|null>(null);function locate(){navigator.geolocation?.getCurrentPosition(p=>{setCoords({lat:p.coords.latitude,lng:p.coords.longitude});setMsg('✓ Localização capturada.')},()=>setMsg('Não conseguimos acessar sua localização. O cadastro pode continuar com o endereço informado.'),{enableHighAccuracy:true,timeout:10000})}async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setMsg('');const f:any=Object.fromEntries(new FormData(e.currentTarget).entries());f.role=role;f.latitude=coords?.lat;f.longitude=coords?.lng;f.showExactLocation=f.showExactLocation?'1':'0';try{const out=await api('/api/auth/register',{method:'POST',body:JSON.stringify(f)});setMsg(`Conta criada! ${role==='professional'?(out.locationSource==='gps'?'Localização do mapa definida pelo GPS. ':out.locationSource==='address'?'Localização do mapa definida automaticamente pelo endereço cadastrado. ':'Não foi possível localizar o endereço agora; você poderá atualizar pelo perfil. '):''}Anote seu código de recuperação: ${out.recoveryCode}`)}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}return <Modal onClose={onClose} wide><div className="eyebrow">CADASTRO</div><h2>Crie sua conta no ServPerto</h2><div className="roleToggle"><button className={role==='client'?'active':''} onClick={()=>setRole('client')}>Sou cliente</button><button className={role==='professional'?'active':''} onClick={()=>setRole('professional')}>Sou profissional</button></div><form onSubmit={submit} className="formGrid"><label>Nome completo<input name="name" required/></label><label>WhatsApp<input name="phone" required/></label><label>CEP<input name="cep" required/></label><label>Cidade<input name="city" defaultValue="Manaus" required/></label><label className="span2">Endereço completo<input name="address" required/></label>{role==='professional'&&<><label>Categoria principal<input name="category" list="regCats" required placeholder="Ex.: Técnico em informática"/><datalist id="regCats">{examples.map(x=><option key={x} value={x}/>)}</datalist></label><label>Serviços oferecidos<input name="services" placeholder="Formatação, redes, manutenção"/></label><label className="span2">Descrição profissional<textarea name="description" rows={3} placeholder="Conte sua experiência e especialidades"/></label><label className="check span2"><input type="checkbox" name="showExactLocation"/> Exibir meu ponto exato no mapa público</label></>}<label>Nome de login<input name="username" minLength={4} required/></label><label>Senha de acesso<input name="password" type="password" minLength={8} required/></label><label className="check span2"><input type="checkbox" required/> Li e aceito os Termos de Uso e a Política de Privacidade.</label><button type="button" className="secondary span2" onClick={locate}>📍 Usar localização atual neste cadastro</button>{role==='professional'&&<small className="span2 locationHint">Se você não usar o GPS, o ServPerto localizará automaticamente o prestador pelo endereço e CEP informados no cadastro.</small>}{msg&&<div className={`span2 ${msg.startsWith('Conta')||msg.startsWith('✓')?'okText':'errorText'}`}>{msg}</div>}<button className="primary span2" disabled={busy}>{busy?'Criando...':'Criar minha conta'}</button></form></Modal>}

function ProfileModal({id,onClose,onRequest,onFavorite,canFavorite}:{id:number,onClose:()=>void,onRequest:(p:Professional)=>void,onFavorite?:(id:number)=>void,canFavorite?:boolean}){const[data,setData]=useState<ProfileDetail|null>(null);useEffect(()=>{api(`/api/professionals/${id}`).then(setData).catch(()=>setData(null))},[id]);if(!data)return <Modal onClose={onClose}><p>Carregando perfil...</p></Modal>;const p=data.professional;return <Modal onClose={onClose} wide><div className="profileHero"><Avatar name={p.name} image={p.image} big/><div><div className="eyebrow">PERFIL PROFISSIONAL</div><h2>{p.name} {p.verified?'✓':''}</h2><p>⭐ {p.review_count?`${Number(p.rating).toFixed(1)} — ${p.review_count} avaliações`:'Novo no ServPerto'} · 📍 {p.city||'Manaus - AM'}</p></div></div><section className="profileSection"><h3>Sobre o profissional</h3><p>{p.description||'Este profissional ainda não adicionou uma apresentação.'}</p></section><section className="profileSection"><h3>Serviços oferecidos</h3><div className="chips">{data.services.map(s=><span key={s.id}>{s.title}{s.price_from?` · a partir de ${BRL.format(s.price_from)}`:''}</span>)}</div></section><section className="profileSection"><h3>Avaliações</h3>{data.reviews.length?data.reviews.map(r=><div className="review" key={r.id}><b>{stars(r.rating)} {r.rating}/5</b><p>{r.comment||'Sem comentário.'}</p><small>{r.client_name} · {new Date(r.created_at).toLocaleDateString('pt-BR')}</small></div>):<p>Ainda não há avaliações.</p>}</section><div className="actionRow"><button className="primary" disabled={p.available===0} onClick={()=>onRequest(p)}>{p.available===0?'Profissional indisponível':'Solicitar orçamento'}</button>{canFavorite&&<button className="secondary" onClick={()=>onFavorite?.(p.id)}>♡ Favoritar</button>}</div></Modal>}


function ProfileImageControl({user,onUpdated}:{user:User;onUpdated:()=>Promise<void>}){const[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);async function change(e:React.ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return;setBusy(true);setMsg('');try{const image=await compressProfileImage(file);await api('/api/profile/image',{method:'PUT',headers:authHeaders(),body:JSON.stringify({image})});setMsg('Foto atualizada.');await onUpdated()}catch(e:any){setMsg(e.message)}finally{setBusy(false);e.target.value=''}}async function remove(){setBusy(true);try{await api('/api/profile/image',{method:'DELETE',headers:authHeaders()});setMsg('Foto removida.');await onUpdated()}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}return <div className="profileImageBox"><Avatar name={user.name} image={user.image} big/><div><b>Imagem de perfil (opcional)</b><p>JPG, PNG ou WebP. A imagem é reduzida automaticamente para proteger o desempenho.</p><label className="uploadBtn">{busy?'Processando...':'Escolher foto'}<input type="file" accept="image/jpeg,image/png,image/webp" onChange={change} disabled={busy}/></label>{user.image&&<button type="button" className="dangerLink" onClick={remove} disabled={busy}>Remover foto</button>}{msg&&<small>{msg}</small>}</div></div>}

function DeleteAccountControl({onDeleted}:{onDeleted:()=>void}){const[busy,setBusy]=useState(false),[confirmText,setConfirmText]=useState(''),[msg,setMsg]=useState('');async function remove(){if(confirmText.trim().toUpperCase()!=='EXCLUIR')return setMsg('Digite EXCLUIR para confirmar.');if(!confirm('Deseja realmente desativar sua conta no ServPerto? Seu perfil deixará de aparecer na plataforma.'))return;setBusy(true);setMsg('');try{await api('/api/account',{method:'DELETE',headers:authHeaders(),body:JSON.stringify({confirm:'EXCLUIR'})});onDeleted()}catch(e:any){setMsg(e.message);setBusy(false)}}return <div className="dangerZone"><div><h3>Excluir minha conta</h3><p>Sua conta será desativada e deixará de aparecer no ServPerto. O histórico necessário para segurança e integridade dos atendimentos será preservado.</p></div><input value={confirmText} onChange={e=>setConfirmText(e.target.value)} placeholder="Digite EXCLUIR"/><button className="dangerButton" type="button" disabled={busy||confirmText.trim().toUpperCase()!=='EXCLUIR'} onClick={remove}>{busy?'Excluindo...':'Excluir minha conta'}</button>{msg&&<small className="errorText">{msg}</small>}</div>}

function ChatModal({request,userRole,onClose}:{request:ServiceRequest;userRole:'client'|'provider';onClose:()=>void}){const[data,setData]=useState<any>(null),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false),endRef=useRef<HTMLDivElement>(null);async function load(){try{const d=await api(`/api/service-requests/${request.id}/chat`,{headers:authHeaders()});setData(d);setTimeout(()=>endRef.current?.scrollIntoView({behavior:'smooth'}),50)}catch(e:any){setMsg(e.message)}}useEffect(()=>{load();const t=setInterval(load,5000);return()=>clearInterval(t)},[request.id]);async function send(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const f=new FormData(form);const text=String(f.get('message')||'').trim();if(!text)return;setBusy(true);setMsg('');try{await api(`/api/service-requests/${request.id}/chat`,{method:'POST',headers:authHeaders(),body:JSON.stringify({type:'text',message:text})});form.reset();await load()}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}function shareLocation(){if(!navigator.geolocation)return setMsg('Geolocalização não disponível neste dispositivo.');setBusy(true);navigator.geolocation.getCurrentPosition(async p=>{try{await api(`/api/service-requests/${request.id}/chat`,{method:'POST',headers:authHeaders(),body:JSON.stringify({type:'location',latitude:p.coords.latitude,longitude:p.coords.longitude,message:'Minha localização para o atendimento.'})});await load()}catch(e:any){setMsg(e.message)}finally{setBusy(false)}},()=>{setMsg('Não foi possível acessar sua localização.');setBusy(false)},{enableHighAccuracy:true,timeout:12000})}async function closeChat(){if(!confirm('Encerrar este chat? Depois disso não será possível enviar novas mensagens.'))return;try{await api(`/api/service-requests/${request.id}/chat/close`,{method:'POST',headers:authHeaders()});await load()}catch(e:any){setMsg(e.message)}}const chat=data?.chat;const messages:ChatMessage[]=data?.messages||[];return <Modal onClose={onClose} wide><div className="eyebrow">CHAT DO SERVIÇO</div><h2>{chat?`${chat.clientName} ↔ ${chat.providerName}`:'Carregando conversa...'}</h2><p>Serviço: <b>{request.title}</b></p>{msg&&<div className="errorText">{msg}</div>}<div className="chatWindow">{messages.length?messages.map(m=><div key={m.id} className={`chatMsg ${m.sender_user_id===data?.currentUserId?'mine':''}`}><b>{m.sender_name}</b>{m.message_type==='location'?<><p>📍 {m.message||'Localização compartilhada'}</p><a href={`https://www.openstreetmap.org/?mlat=${m.latitude}&mlon=${m.longitude}#map=17/${m.latitude}/${m.longitude}`} target="_blank" rel="noreferrer">Abrir localização no mapa</a></>:<p>{m.message}</p>}<small>{new Date(m.created_at).toLocaleString('pt-BR')}</small></div>):<div className="empty">Conversa iniciada. Envie a primeira mensagem.</div>}<div ref={endRef}/></div>{chat?.status==='open'?<><form className="chatComposer" onSubmit={send}><input name="message" maxLength={2000} placeholder="Digite sua mensagem..." autoComplete="off"/><button className="primary" disabled={busy}>Enviar</button></form><div className="actionRow">{userRole==='client'&&<button className="secondary" onClick={shareLocation} disabled={busy}>📍 Enviar minha localização</button>}{userRole==='client'&&<button className="dangerLink" onClick={closeChat}>Encerrar chat</button>}</div></>:<div className="closedChat">🔒 Chat encerrado pelo cliente.</div>}</Modal>}

function RequestModal({professional,onClose,onCreated}:{professional:Professional,onClose:()=>void,onCreated:()=>void}){const[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const f=Object.fromEntries(new FormData(e.currentTarget).entries());try{await api('/api/service-requests',{method:'POST',headers:authHeaders(),body:JSON.stringify({...f,providerId:professional.id})});setMsg('Solicitação enviada com sucesso.');setTimeout(()=>{onCreated();onClose()},700)}catch(e:any){setMsg(e.message)}finally{setBusy(false)}}return <Modal onClose={onClose}><div className="eyebrow">SOLICITAR ORÇAMENTO</div><h2>{professional.name}</h2><p>Descreva o serviço com detalhes para receber um orçamento mais preciso.</p><form onSubmit={submit} className="formGrid one"><label>Serviço<input name="title" defaultValue={professional.category} required/></label><label>Descrição<textarea name="description" rows={5} minLength={5} required placeholder="Explique o problema, equipamento/local e o que precisa ser feito."/></label><label>Local do serviço<input name="address" placeholder="Bairro ou endereço"/></label>{msg&&<div className={msg.startsWith('Solicitação')?'okText':'errorText'}>{msg}</div>}<button className="primary" disabled={busy}>{busy?'Enviando...':'Enviar solicitação'}</button></form></Modal>}

function QuoteModal({request,onClose,onDone}:{request:ServiceRequest,onClose:()=>void,onDone:()=>void}){const[msg,setMsg]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget).entries());try{await api(`/api/service-requests/${request.id}/quote`,{method:'POST',headers:authHeaders(),body:JSON.stringify(f)});onDone();onClose()}catch(e:any){setMsg(e.message)}}return <Modal onClose={onClose}><div className="eyebrow">ENVIAR ORÇAMENTO</div><h2>{request.title}</h2><p>Cliente: {request.client_name}</p><form onSubmit={submit} className="formGrid one"><label>Valor (R$)<input name="price" type="number" min="1" step="0.01" defaultValue={request.quote_price||''} required/></label><label>Mensagem<textarea name="message" rows={4} defaultValue={request.quote_message||''} placeholder="Prazo, materiais inclusos, condições..."/></label>{msg&&<div className="errorText">{msg}</div>}<button className="primary">Enviar orçamento</button></form></Modal>}

function ReviewModal({request,onClose,onDone}:{request:ServiceRequest,onClose:()=>void,onDone:()=>void}){const[msg,setMsg]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget).entries());try{await api('/api/reviews',{method:'POST',headers:authHeaders(),body:JSON.stringify({...f,requestId:request.id})});onDone();onClose()}catch(e:any){setMsg(e.message)}}return <Modal onClose={onClose}><div className="eyebrow">AVALIAR SERVIÇO</div><h2>Como foi sua experiência?</h2><form onSubmit={submit} className="formGrid one"><label>Nota<select name="rating" defaultValue="5"><option value="5">⭐⭐⭐⭐⭐ Excelente</option><option value="4">⭐⭐⭐⭐ Muito bom</option><option value="3">⭐⭐⭐ Bom</option><option value="2">⭐⭐ Regular</option><option value="1">⭐ Ruim</option></select></label><label>Comentário<textarea name="comment" rows={4} placeholder="Conte como foi o atendimento"/></label>{msg&&<div className="errorText">{msg}</div>}<button className="primary">Publicar avaliação</button></form></Modal>}

function ReputationBadges({p}:{p:Professional}){const badges:string[]=[];if(p.verified)badges.push('✓ Verificado');if((p.completed_count||0)>=5)badges.push('🏆 Experiente');if((p.rating||0)>=4.7&&(p.review_count||0)>=3)badges.push('⭐ Bem avaliado');if(p.available!==0)badges.push('⚡ Disponível');return badges.length?<div className="reputationBadges">{badges.slice(0,3).map(x=><span key={x}>{x}</span>)}</div>:null}
function NotificationCenter(){const[open,setOpen]=useState(false),[items,setItems]=useState<Notice[]>([]);async function load(){const o=await api('/api/notifications',{headers:authHeaders()}).catch(()=>({notifications:[]}));setItems(o.notifications||[])}useEffect(()=>{load();const t=setInterval(load,45000);return()=>clearInterval(t)},[]);const unread=items.filter(x=>!x.read_at).length;async function mark(id?:number){await api('/api/notifications/read',{method:'POST',headers:authHeaders(),body:JSON.stringify(id?{id}:{all:true})});await load()}return <div className="notificationWrap"><button className="notificationBell" onClick={()=>{setOpen(!open);if(!open)load()}}>🔔{unread>0&&<b>{unread>9?'9+':unread}</b>}</button>{open&&<div className="notificationPanel"><div className="notificationHead"><strong>Notificações</strong>{unread>0&&<button onClick={()=>mark()}>Marcar todas como lidas</button>}</div>{items.length?items.slice(0,20).map(n=><button className={`notificationItem ${n.read_at?'':'unread'}`} key={n.id} onClick={()=>mark(n.id)}><span>{n.kind==='quote'?'💰':n.kind==='message'?'💬':n.kind==='schedule'?'📅':n.kind==='review'?'⭐':'🔔'}</span><div><b>{n.title}</b><small>{n.message}</small><time>{new Date(n.created_at).toLocaleString('pt-BR')}</time></div></button>):<div className="empty mini">Nenhuma notificação.</div>}</div>}</div>}
function PortfolioManager(){const[items,setItems]=useState<PortfolioItem[]>([]),[msg,setMsg]=useState('');async function load(){const o=await api('/api/provider/portfolio',{headers:authHeaders()}).catch(()=>({items:[]}));setItems(o.items||[])}useEffect(()=>{load()},[]);async function add(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget;const input=form.elements.namedItem('photo') as HTMLInputElement;const file=input.files?.[0];if(!file)return setMsg('Escolha uma foto.');try{const image=await compressProfileImage(file);const caption=String(new FormData(form).get('caption')||'');await api('/api/provider/portfolio',{method:'POST',headers:authHeaders(),body:JSON.stringify({image,caption})});form.reset();setMsg('Foto adicionada ao portfólio.');load()}catch(e:any){setMsg(e.message)}}async function remove(id:number){await api(`/api/provider/portfolio/${id}`,{method:'DELETE',headers:authHeaders()});load()}return <div className="portfolioManage"><form className="panelCard formGrid one" onSubmit={add}><h3>Adicionar trabalho ao portfólio</h3><label>Foto<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required/></label><label>Legenda<input name="caption" maxLength={180} placeholder="Ex.: Manutenção completa de notebook"/></label>{msg&&<small>{msg}</small>}<button className="primary">Adicionar ao portfólio</button></form><div className="portfolioGrid">{items.map(x=><article key={x.id}><img src={x.file_url} alt={x.caption||'Trabalho realizado'}/><div><span>{x.caption||'Trabalho realizado'}</span><button className="dangerLink" onClick={()=>remove(x.id)}>Remover</button></div></article>)}</div></div>}
function ScheduleModal({request,onClose,onDone}:{request:ServiceRequest;onClose:()=>void;onDone:()=>void}){const[msg,setMsg]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const v=String(new FormData(e.currentTarget).get('scheduledAt')||'');try{await api(`/api/service-requests/${request.id}/schedule`,{method:'POST',headers:authHeaders(),body:JSON.stringify({scheduledAt:v})});onDone();onClose()}catch(e:any){setMsg(e.message)}}return <Modal onClose={onClose}><div className="eyebrow">AGENDA DO SERVIÇO</div><h2>Agendar atendimento</h2><p>{request.title}</p><form className="formGrid one" onSubmit={submit}><label>Data e horário<input name="scheduledAt" type="datetime-local" defaultValue={request.scheduled_at?new Date(request.scheduled_at).toISOString().slice(0,16):''} required/></label>{msg&&<div className="errorText">{msg}</div>}<button className="primary">Salvar agendamento</button></form></Modal>}

function ProfessionalCards({items,onProfile,onRequest,onFavorite}:{items:Professional[],onProfile:(id:number)=>void,onRequest:(p:Professional)=>void,onFavorite?:(id:number)=>void}){return <div className="professionalGrid">{items.map(p=><article className="professionalCard" key={p.id}><div className="proTop"><Avatar name={p.name} image={p.image}/><div className="proIdentity"><h3>{p.name} {p.verified?'✓':''}</h3><div className="proRating">⭐ {p.review_count?`${Number(p.rating).toFixed(1)} (${p.review_count} avaliações)`:'Novo no ServPerto'}</div></div></div><ReputationBadges p={p}/><div className="proMeta"><span>🧰 <b>{p.category}</b></span>{p.city&&<span>🏙️ {p.city}</span>}{p.distanceKm!=null&&<span>📍 {p.distanceKm.toFixed(1)} km de distância</span>}<span className={p.available===0?'unavailable':'available'}>{p.available===0?'⚪ Indisponível':'🟢 Disponível'}</span></div>{p.description&&<p className="proDescription">{p.description}</p>}<div className="cardActions"><button onClick={()=>onProfile(p.id)}>Ver perfil</button><button className="outline" disabled={p.available===0} onClick={()=>onRequest(p)}>{p.available===0?'Indisponível':'Solicitar orçamento'}</button>{onFavorite&&<button className="iconBtn" aria-label={`Favoritar ${p.name}`} onClick={()=>onFavorite(p.id)}>♡</button>}</div></article>)}</div>}

function ClientDashboard({session,professionals,onLogout,onProfile,onRequest,refreshNonce,onRefreshSession}:{session:SessionData;professionals:Professional[];onLogout:()=>void;onProfile:(id:number)=>void;onRequest:(p:Professional)=>void;refreshNonce:number;onRefreshSession:()=>Promise<void>}){const[tab,setTab]=useState('overview'),[q,setQ]=useState(''),[category,setCategory]=useState(''),[requests,setRequests]=useState<ServiceRequest[]>([]),[favorites,setFavorites]=useState<Professional[]>([]),[reviewReq,setReviewReq]=useState<ServiceRequest|null>(null),[chatReq,setChatReq]=useState<ServiceRequest|null>(null),[notice,setNotice]=useState(''),[userPos,setUserPos]=useState<{lat:number,lng:number}|null>(null),[geoMsg,setGeoMsg]=useState('');async function load(){const[r,f]=await Promise.all([api('/api/service-requests',{headers:authHeaders()}).catch(()=>({requests:[]})),api('/api/favorites',{headers:authHeaders()}).catch(()=>({favorites:[]}))]);setRequests(r.requests||[]);setFavorites(f.favorites||[])}useEffect(()=>{load()},[refreshNonce]);const categories=useMemo(()=>Array.from(new Set(professionals.map(p=>p.category).filter(Boolean))).sort(),[professionals]);const filtered=useMemo(()=>professionals.filter(p=>(!category||p.category.toLowerCase().includes(category.toLowerCase()))&&(!q||`${p.name} ${p.category} ${p.description||''}`.toLowerCase().includes(q.toLowerCase()))).map(p=>({...p,distanceKm:userPos?distanceKm(userPos.lat,userPos.lng,p.latitude,p.longitude):undefined})).sort((a,b)=>userPos?(a.distanceKm!-b.distanceKm!):(b.rating-a.rating||b.review_count-a.review_count)).slice(0,60),[professionals,q,category,userPos]);function locate(){navigator.geolocation?.getCurrentPosition(p=>{setUserPos({lat:p.coords.latitude,lng:p.coords.longitude});setGeoMsg('✓ Sua localização foi adicionada ao mapa.')},()=>setGeoMsg('Não conseguimos acessar sua localização. Você ainda pode navegar pelos profissionais no mapa.'),{enableHighAccuracy:true,timeout:10000})}async function favorite(id:number){await api('/api/favorites',{method:'POST',headers:authHeaders(),body:JSON.stringify({providerId:id})});setNotice('Profissional adicionado aos favoritos.');load()}async function unfavorite(id:number){await api(`/api/favorites/${id}`,{method:'DELETE',headers:authHeaders()});load()}async function decision(r:ServiceRequest,d:'accepted'|'rejected'){await api(`/api/quotes/${r.quote_id}/decision`,{method:'POST',headers:authHeaders(),body:JSON.stringify({decision:d})});setNotice(d==='accepted'?'Orçamento aceito. O chat com o profissional foi liberado.':'Orçamento recusado.');await load()}async function cancel(r:ServiceRequest){await api(`/api/service-requests/${r.id}/status`,{method:'POST',headers:authHeaders(),body:JSON.stringify({action:'cancel'})});load()}return <DashboardShell user={session.user} tab={tab} setTab={setTab} onLogout={onLogout} items={[['overview','Visão geral'],['search','Mapa e profissionais'],['requests','Meus pedidos'],['agenda','Minha agenda'],['favorites','Favoritos'],['profile','Meu perfil']]}> {notice&&<div className="okText">{notice}</div>}{tab==='overview'&&<><div className="welcome"><div><div className="eyebrow">PAINEL DO CLIENTE</div><h1>Olá, {session.user.name.split(' ')[0]} 👋</h1><p>Encontre profissionais no mapa, solicite orçamentos, converse após o aceite e acompanhe seus serviços.</p></div><button className="primary" onClick={()=>setTab('search')}>Explorar mapa</button></div><div className="stats"><article><b>{requests.length}</b><span>Solicitações</span></article><article><b>{requests.filter(r=>r.status==='quoted').length}</b><span>Orçamentos recebidos</span></article><article><b>{requests.filter(r=>r.status==='completed').length}</b><span>Serviços concluídos</span></article><article><b>{favorites.length}</b><span>Favoritos</span></article></div></>}{tab==='search'&&<section><div className="panelTitle"><h2>Mapa de profissionais</h2><p>Escolha uma categoria para visualizar no mapa somente os profissionais daquele serviço.</p></div><div className="clientMapControls"><select value={category} onChange={e=>setCategory(e.target.value)}><option value="">Todas as categorias</option>{categories.map(c=><option key={c} value={c}>{c}</option>)}</select><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar por nome ou serviço..."/><button className="primary" onClick={locate}>📍 Minha localização</button></div>{geoMsg&&<small>{geoMsg}</small>}<div className="clientMapLayout"><div className="panelCard mapPanelCard"><MapPanel items={filtered} userPos={userPos} onOpen={onProfile}/><div className="mapLegend"><span>📍 {filtered.length} profissionais exibidos</span>{category&&<b>{category}</b>}</div></div><div><ProfessionalCards items={filtered.slice(0,24)} onProfile={onProfile} onRequest={onRequest} onFavorite={favorite}/></div></div></section>}{tab==='requests'&&<section><div className="panelTitle"><h2>Meus pedidos</h2><p>Acompanhe cada etapa do atendimento.</p></div><div className="requestList">{requests.length?requests.map(r=><article className="requestCard" key={r.id}><div className="requestHead"><div><h3>{r.title}</h3><p>{r.provider_name}</p></div><span className={`badge ${r.status}`}>{statusLabel[r.status]||r.status}</span></div><p>{r.description}</p>{r.scheduled_at&&<div className="scheduleChip">📅 Agendado para {new Date(r.scheduled_at).toLocaleString('pt-BR')}</div>}{r.quote_id&&<div className="quoteBox"><b>Orçamento: {BRL.format(Number(r.quote_price||0))}</b><span>{r.quote_message||'Sem observações.'}</span>{r.quote_status==='pending'&&<div className="actionRow"><button className="primary" onClick={()=>decision(r,'accepted')}>Aceitar orçamento</button><button className="secondary" onClick={()=>decision(r,'rejected')}>Recusar</button></div>}</div>}<div className="requestFooter"><small>{new Date(r.created_at).toLocaleString('pt-BR')}</small>{['open','quoted'].includes(r.status)&&<button className="dangerLink" onClick={()=>cancel(r)}>Cancelar solicitação</button>}{['accepted','in_progress','completed'].includes(r.status)&&r.quote_status==='accepted'&&<button className="secondary small" onClick={()=>setChatReq(r)}>💬 Abrir chat</button>}{r.status==='completed'&&!r.review_id&&<button className="primary small" onClick={()=>setReviewReq(r)}>⭐ Avaliar serviço</button>}{r.review_id&&<span className="reviewDone">✓ Avaliação já realizada</span>}</div></article>):<div className="empty">Você ainda não enviou solicitações.</div>}</div></section>}{tab==='agenda'&&<section><div className="panelTitle"><h2>Minha agenda</h2><p>Atendimentos com data marcada.</p></div><div className="agendaList">{requests.filter(r=>r.scheduled_at&&['accepted','in_progress','completed'].includes(r.status)).length?requests.filter(r=>r.scheduled_at&&['accepted','in_progress','completed'].includes(r.status)).sort((a,b)=>Date.parse(a.scheduled_at!)-Date.parse(b.scheduled_at!)).map(r=><article className="agendaCard" key={r.id}><div className="calendarDate"><b>{new Date(r.scheduled_at!).toLocaleDateString('pt-BR',{day:'2-digit'})}</b><span>{new Date(r.scheduled_at!).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</span></div><div><h3>{r.title}</h3><p>{r.provider_name}</p><b>🕒 {new Date(r.scheduled_at!).toLocaleString('pt-BR')}</b><small>{statusLabel[r.status]||r.status}</small></div></article>):<div className="empty">Nenhum atendimento agendado ainda.</div>}</div></section>}{tab==='favorites'&&<section><div className="panelTitle"><h2>Favoritos</h2></div>{favorites.length?<div className="professionalGrid">{favorites.map(p=><article className="professionalCard" key={p.id}><div className="proTop"><Avatar name={p.name} image={p.image}/><div><h3>{p.name}</h3><small>⭐ {Number(p.rating||0).toFixed(1)}</small></div></div><p>🧰 {p.category}</p><div className="cardActions"><button onClick={()=>onProfile(p.id)}>Ver perfil</button><button className="outline" onClick={()=>onRequest(p)}>Orçamento</button><button className="iconBtn" onClick={()=>unfavorite(p.id)}>♥</button></div></article>)}</div>:<div className="empty">Nenhum favorito ainda.</div>}</section>}{tab==='profile'&&<section><div className="panelTitle"><h2>Meu perfil</h2><p>A foto é opcional e poderá ser removida a qualquer momento.</p></div><div className="panelCard"><ProfileImageControl user={session.user} onUpdated={onRefreshSession}/><div className="profileData"><p><b>Nome:</b> {session.user.name}</p><p><b>WhatsApp:</b> {session.user.phone}</p><p><b>Cidade:</b> {session.user.city}</p></div></div><DeleteAccountControl onDeleted={onLogout}/></section>}{reviewReq&&<ReviewModal request={reviewReq} onClose={()=>setReviewReq(null)} onDone={load}/>} {chatReq&&<ChatModal request={chatReq} userRole="client" onClose={()=>setChatReq(null)}/>}</DashboardShell>}

